/**
 * Cloudflare Worker entry: the OpenNext-built Next.js app, plus a scheduled handler that runs the alert job.
 * wrangler.jsonc points `main` here and declares the cron schedule under `triggers`.
 */
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore generated by `opennextjs-cloudflare build`
import worker from './.open-next/worker.js';

interface Env { CRON_SECRET?: string; APP_URL?: string; [k: string]: unknown }
interface Ctx { waitUntil(p: Promise<unknown>): void }

export default {
  fetch: worker.fetch as (req: Request, env: Env, ctx: Ctx) => Promise<Response>,

  /** Every cron tick: call the app's own alert endpoint, authenticated with CRON_SECRET. */
  async scheduled(_event: unknown, env: Env, ctx: Ctx) {
    if (!env.CRON_SECRET || !env.APP_URL) { console.error('[cron] set CRON_SECRET and APP_URL to run email alerts'); return; }
    const req = new Request(`${env.APP_URL.replace(/\/+$/, '')}/api/cron/alerts`, { method: 'POST', headers: { authorization: `Bearer ${env.CRON_SECRET}` } });
    ctx.waitUntil((worker.fetch(req, env, ctx) as Promise<Response>).then(async r => { if (!r.ok) console.error('[cron] alerts endpoint answered', r.status, (await r.text()).slice(0, 200)); }));
  },
};

// Durable Objects the OpenNext build can reference (only used if the cache options in open-next.config.ts turn them on).
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from './.open-next/worker.js';
